WITH with_last AS (SELECT s.*, latest.transaction_amount, latest.transaction_merchant FROM accounts s LEFT JOIN LATERAL (SELECT c.amount AS transaction_amount, c.merchant AS transaction_merchant FROM transactions c WHERE c.account_id = s.id ORDER BY c.amount DESC, c.id DESC LIMIT 1) latest ON TRUE) SELECT s.id, s.customer_id, s.account_type, s.balance, s.opened_date, s.status, CASE WHEN account_type RLIKE '^(SAVINGS|CHECKING)$' THEN 'OTHER_ZONE' WHEN account_type RLIKE '^(CREDIT|LOAN)$' THEN 'GROUP_A' ELSE 'PRIORITY' END AS account_type_zone, (SELECT MIN(x.monthly_fee) FROM subscriptions x WHERE x.customer_id = s.customer_id) AS min_subscription_monthly_fee FROM with_last s;
